def from_roman(s):
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Validate uppercase only
    if not s.isupper():
        raise ValueError("Only uppercase letters are allowed")

    # Validate characters
    valid_chars = set('IVXLCDM')
    if not all(c in valid_chars for c in s):
        raise ValueError("Invalid characters in Roman numeral")

    # Standard form validation: check for repeated subtractive patterns
    # and invalid sequences

    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check for invalid repetitions
    # V, L, D cannot repeat
    for i in range(len(s) - 1):
        if s[i] in 'VLD' and s[i] == s[i+1]:
            raise ValueError(f"Invalid repetition of {s[i]}")

    # I, X, C, M can repeat at most 3 times consecutively
    i = 0
    while i < len(s):
        count = 1
        while i + count < len(s) and s[i + count] == s[i]:
            count += 1
        if s[i] in 'IVXLCDM' and count > 3:
            raise ValueError(f"Too many repetitions of {s[i]}")
        i += count

    # Check for valid subtractive pairs
    valid_pairs = {
        'I': ['V', 'X'],
        'X': ['L', 'C'],
        'C': ['D', 'M']
    }

    i = 0
    while i < len(s) - 1:
        if roman_map[s[i]] < roman_map[s[i+1]]:
            if s[i] not in valid_pairs or s[i+1] not in valid_pairs[s[i]]:
                raise ValueError(f"Invalid subtractive pair: {s[i]}{s[i+1]}")
            # After a subtractive pair, skip the next character
            i += 2
        else:
            i += 1

    # Convert to integer
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_map[s[i]] < roman_map[s[i+1]]:
            total += roman_map[s[i+1]] - roman_map[s[i]]
            i += 2
        else:
            total += roman_map[s[i]]
            i += 1

    # Validate range 1-3999
    if total < 1 or total > 3999:
        raise ValueError("Roman numeral out of range 1-3999")

    return total

